WITH cleaned AS (SELECT id, customer_id, order_date, status, channel, amount, shipping_fee, CONCAT_WS('/', channel, status) AS channel_status_key, INITCAP(TRIM(status)) AS status_title FROM orders WHERE discount >= 0.25) SELECT DATE_TRUNC('YEAR', order_date) AS year_start, SUM(CASE WHEN channel = 'store' THEN shipping_fee ELSE 0 END) AS store_shipping_fee, STDDEV_SAMP(amount) AS amount_stddev, SIZE(COLLECT_SET(channel)) AS num_channels, COUNT(*) FILTER (WHERE channel = 'mobile') AS mobile_rows, COUNT_IF(status = 'SHIPPED') AS shipped_events FROM cleaned GROUP BY DATE_TRUNC('YEAR', order_date);
